// spec: .qa/e2e/specs/prayer-catalog.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

// Карточки каталога: кнопки с «נוסח התפילה אשכנזי» в имени; название — до « — » / после «פתיחת ».
function cards(page: Page) {
  return page.getByRole('button', { name: /נוסח התפילה אשכנזי/ });
}
async function titles(page: Page) {
  const labels = await cards(page).evaluateAll((els) => els.map((e) => e.getAttribute('aria-label') || ''));
  return labels.map((l) => l.split(' — ')[0].split(', נוסח')[0].replace(/^פתיחת /, ''));
}

test.describe('Каталог молитв', () => {
  test('PC-01 /prayers: список с נוסח, поиск по синонимам и נוסח, пустое состояние, открытие #6a86f7ff @prod-safe', async ({ page }) => {
    // 1. Открыть `/prayers`.
    await page.goto('/prayers');
    const search = page.getByRole('textbox', { name: 'חיפוש' });
    await expect(search).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('התפילות מוצגות בנוסח אשכנז שנשמר בפרופיל.')).toBeVisible();
    await expect(cards(page).first()).toBeVisible();
    const allCount = await cards(page).count();
    expect(allCount).toBeGreaterThanOrEqual(3);
    await expect(page.getByText('נוסח התפילה אשכנזי').first()).toBeVisible();

    // 2. По очереди ввести в поиск запросы и прочитать список карточек.
    await search.fill('מעריב');
    await expect.poll(() => titles(page)).toEqual(['ערבית']);

    await search.fill('עמידה');
    await expect.poll(() => titles(page)).toEqual(['שחרית', 'מנחה', 'ערבית']);

    await search.fill('שמונה עשרה');
    await expect.poll(() => titles(page)).toEqual(['שחרית', 'מנחה', 'ערבית']);

    await search.fill('ק״ש שעל המיטה');
    await expect.poll(() => titles(page)).toEqual(['קריאת שמע על המיטה']);

    await search.fill('קידוש לבנה');
    await expect.poll(() => titles(page)).toEqual(['ברכת הלבנה']);

    await search.fill('אשכנז');
    await expect.poll(() => cards(page).count()).toBe(allCount);

    await search.fill('zzzqq');
    await expect(page.getByText('לא נמצאו תפילות שמתאימות ל״zzzqq״.')).toBeVisible();
    await expect(cards(page)).toHaveCount(0);

    // 3. Нажать «ניקוי החיפוש» — полный список.
    await page.getByRole('button', { name: 'ניקוי החיפוש' }).click();
    await expect.poll(() => cards(page).count()).toBe(allCount);

    // Нет горизонтальной прокрутки.
    const noHScroll = await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth);
    expect(noHScroll).toBe(true);

    // 4. Ввести «מעריב» → клик по карточке (раскрывает строку, затем «פתיחת ערבית»).
    await search.fill('מעריב');
    await expect.poll(() => titles(page)).toEqual(['ערבית']);
    await cards(page).first().click();
    await page.getByRole('button', { name: /^פתיחת ערבית/ }).click();
    await expect(page).toHaveURL(/\/prayer\/arvit_ashkenaz$/);
  });
});
